// 1) Deterministic PRNG + Bộ sinh Lead giả lập Việt Nam (0% PII thật)
import crypto from 'node:crypto';

function mulberry32(seed: number) {
  return function () {
    let t = (seed += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const LAST_NAMES = ['Nguyễn', 'Trần', 'Lê', 'Phạm', 'Huỳnh', 'Võ', 'Đặng', 'Bùi'];
const MIDDLE_NAMES = ['Văn', 'Thị', 'Minh', 'Gia', 'Thanh', 'Quốc', 'Hoàng', 'Ngọc'];
const FIRST_NAMES = ['Anh', 'Bảo', 'Châu', 'Dũng', 'Hương', 'Khang', 'Linh', 'Phúc', 'Vy'];
const CARRIER_PREFIXES = ['090', '093', '070', '091', '081', '096', '097', '032', '038'];

export function generateSyntheticLeads(count = 50000, seed = 20261118) {
  const rand = mulberry32(seed);
  const basePhones: string[] = [];
  const rows = [];

  for (let i = 0; i < count; i++) {
    // Bơm 18% bản ghi trùng có chủ đích để stress-test bộ lọc trùng 180 ngày & Redis Lock
    const isDuplicate = i > 100 && rand() < 0.18;
    const rawCanonicalPhone = isDuplicate
      ? basePhones[Math.floor(rand() * basePhones.length)]
      : `${CARRIER_PREFIXES[Math.floor(rand() * CARRIER_PREFIXES.length)]}999${String(i % 10000).padStart(4, '0')}`;

    if (!isDuplicate) basePhones.push(rawCanonicalPhone);

    // Mô phỏng 3 kiểu nhiễu nhập tay thực tế của khách Việt
    const noiseRoll = rand();
    const dirtyPhone =
      noiseRoll < 0.15
        ? `+84 ${rawCanonicalPhone.slice(1, 4)} ${rawCanonicalPhone.slice(4, 7)} ${rawCanonicalPhone.slice(7)}`
        : noiseRoll < 0.25
          ? rawCanonicalPhone.slice(1) // Thiếu số 0 đầu
          : rawCanonicalPhone;

    const fullName = `${LAST_NAMES[Math.floor(rand() * LAST_NAMES.length)]} ${MIDDLE_NAMES[Math.floor(rand() * MIDDLE_NAMES.length)]} ${FIRST_NAMES[Math.floor(rand() * FIRST_NAMES.length)]}`;
    const ts = 1760000000 + i * 3;

    rows.push({
      external_id: `syn_lead_${seed}_${String(i).padStart(6, '0')}`,
      full_name: fullName,
      phone_input: dirtyPhone,
      email: `qa.synthetic.${i}@domation-sandbox.test`, // Chuẩn RFC 2606 không bao giờ gửi ra ngoài
      fbp: rand() < 0.78 ? `fb.1.${ts * 1000}.${Math.floor(1e9 + rand() * 8e9)}` : null,
      fbc: rand() < 0.42 ? `fb.1.${ts * 1000}.IwAR_syn_${i}` : null,
      source: rand() < 0.6 ? 'meta_instant_form' : 'web_3d_landing',
    });
  }
  return rows;
}

// 2) Chốt bảo vệ Meta CAPI: cấm Staging bắn thiếu test_event_code & chuẩn hóa SHA-256
const sha256Norm = (val: string) =>
  crypto.createHash('sha256').update(val.trim().toLowerCase()).digest('hex');

export async function sendCapiSafely(lead: { external_id: string; phone_e164: string; email: string; fbp?: string | null; fbc?: string | null }, eventId: string) {
  const isProd = process.env.APP_ENV === 'production';
  const testCode = process.env.META_TEST_EVENT_CODE;

  if (!isProd && (!testCode || !testCode.startsWith('TEST'))) {
    throw new Error('BLOCKED_CAPI_LEAK: Môi trường phi sản xuất bắt buộc phải có test_event_code hợp lệ!');
  }

  const capiPhoneDigits = lead.phone_e164.replace(/^\+/, ''); // +8490... -> 8490...
  const payload = {
    data: [{
      event_name: 'QualifiedLead',
      event_time: Math.floor(Date.now() / 1000),
      event_id: eventId,
      action_source: 'system_generated',
      user_data: {
        ph: [sha256Norm(capiPhoneDigits)],
        em: [sha256Norm(lead.email)],
        external_id: [sha256Norm(lead.external_id)],
        ...(lead.fbp ? { fbp: lead.fbp } : {}),
        ...(lead.fbc ? { fbc: lead.fbc } : {}),
      },
    }],
    ...(testCode ? { test_event_code: testCode } : {}),
  };

  return fetch(`https://graph.facebook.com/v21.0/${process.env.META_PIXEL_ID}/events?access_token=${process.env.META_CAPI_TOKEN}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
}
